Here is an example of how you might implement the modified Kruskal's algorithm in C++:
```
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Edge {
    int from, to, weight;

    bool operator<(const Edge& other) const {
        return weight < other.weight;
    }
};

struct DisjointSet {
    vector<int> parent;
    vector<int> rank;

    DisjointSet(int n) {
        parent.resize(n);
        rank.resize(n);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void merge(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return;
        }
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
            rank[rootY] += rank[rootX];
        } else {
            parent[rootY] = rootX;
            rank[rootX] += rank[rootY];
        }
    }
};

int maxConnections(int g_nodes, vector<Edge>& g, int max_connections) {
    sort(g.begin(), g.end());

    DisjointSet ds(g_nodes);
    vector<int> connections(g_nodes, 0);
    int result = 0;

    for (const Edge& e : g) {
        int rootX = ds.find(e.from);
        int rootY = ds.find(e.to);
        if (rootX == rootY || connections[rootX] >= max_connections || connections[rootY] >= max_connections) {
            continue;
        }
        ds.merge(rootX, rootY);
        connections[rootX]++;
        connections[rootY]++;
        result += e.weight;
    }

    return result;
}

