    vector<Edge> g = {{0, 1, 10}, {1, 2, 20}, {2, 3, 30}, {3, 4, 40}, {4, 0, 50}};
    int max_connections = 2;
    cout << maxConnections(g_nodes, g, max_connections) << endl;
    return 0;
}
```
