Here is an example code in C++ that examines the headers of a DLL file without loading the whole library:
```c
#include <Windows.h>
#include <fstream>
#include <iostream>

constexpr WORD IMAGE_FILE_DLL = 0x2000;
constexpr WORD IMAGE_FILE_NET_RUN_FROM_SWAP = 0x1000;

int main(int argc, char* argv[]) {
  if (argc < 2) {
    std::cout << "Please provide the path to the DLL." << std::endl;
    return 1;
  }

  // Open the file in binary mode.
  std::ifstream file(argv[1], std::ios::binary | std::ios::ate);
  if (!file.is_open()) {
    std::cout << "Could not open the file." << std::endl;
    return 1;
  }

  // Get the size of the file.
  std::streamsize size = file.tellg();
  file.seekg(0, std::ios::beg);

  // Read the DOS header.
  IMAGE_DOS_HEADER dosHeader;
  file.read(reinterpret_cast<char*>(&dosHeader), sizeof(IMAGE_DOS_HEADER));
  if (dosHeader.e_magic != IMAGE_DOS_SIGNATURE) {
    std::cout << "This is not a valid PE file." << std::endl;
    return 1;
  }

  // Read the NT headers.
  file.seekg(dosHeader.e_lfanew);
  IMAGE_NT_HEADERS32 ntHeaders;
  file.read(reinterpret_cast<char*>(&ntHeaders), sizeof(IMAGE_NT_HEADERS32));
  if (ntHeaders.Signature != IMAGE_NT_SIGNATURE) {
    std::cout << "This is not a valid PE file." << std::endl;
    return 1;
  }

  // Check if the DLL is a managed C# assembly.
  if ((ntHeaders.FileHeader.Characteristics & IMAGE_FILE_DLL) &&
      (ntHeaders.FileHeader.Characteristics & IMAGE_FILE_NET_RUN_FROM_SWAP)) {
    std::cout << "This DLL is a managed C# assembly." << std::endl;
  } else {
    std::cout << "This DLL is not a managed C# assembly." << std::endl;
  }

  return 0;
}
```
This code uses an `ifstream` object to open the DLL file in binary mode, reads the DOS header and the NT headers, and checks the characteristics of the DLL. If the DLL is a managed C# assembly, the `IMAGE_FILE_DLL` and `IMAGE_FILE_NET_RUN_FROM_SWAP` flags will be set in the `Characteristics` field of the `IMAGE_FILE_HEADER` structure in the NT headers.

