```c++
#include <Windows.h>
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <filesystem>

std::unordered_map<std::string, std::vector<std::string>> GetDependenciesInFolder(const std::string& folderPath)
{
    std::unordered_map<std::string, std::vector<std::string>> dependencies;

    for (const auto & entry : std::filesystem::directory_iterator(folderPath))
    {
        const auto path = entry.path();
        if (path.extension() != ".dll")
        {
            continue;
        }

        auto dllDeps = GetDllDependencies(path.string().c_str());
        dependencies[path.string()] = dllDeps;
    }

    return dependencies;
}
