```csharp
public static class UiElementList
{
    private static readonly List<AutomationElement> elements = new List<AutomationElement>();
    private static readonly object lockObject = new object();

    public static void AddElement(AutomationElement element)
    {
        lock (lockObject)
        {
            elements.Add(element);
        }
    }

    public static void RemoveElement(AutomationElement element)
    {
        lock (lockObject)
        {
            elements.Remove(element);
        }
    }

    public static AutomationElement[] GetAllElements()
    {
        lock (lockObject)
        {
            return elements.ToArray();
        }
    }
}

