int request_cs(const void *self) {
    // create message with request type
    Message request = createMessage(MESSAGE_MAGIC, 0, 0, 0, CS_REQUEST);

    // add new_info to the queue
    Info new_info = {time_clock, id};
    push(new_info);

    // send request to all processes
    send_multicast(&id, &request);

    // wait until entered mutex
    while (!entered_mutex()) {
        Message received;
        local_id from = get(&received);
        if (from == 0) {
            continue;
        }
        switch (received.s_header.s_type) {
            case CS_REQUEST: {
                // create message with reply type
                Message response = createMessage(MESSAGE_MAGIC, 0, 0, 0, CS_REPLY);

                // add new_info to the queue
                Info new_info = {received.s_header.s_local_time, from};
                push(new_info);

                // log and send reply
                fprintf(stderr, "%d: process %d CS_REQUEST from %d\n", time_clock, id, from);
                send(&id, from, &response);
                break;
            }
            case CS_REPLY: {
                set_reply(from);

                // log reply
                fprintf(stderr, "process %d CS_REPLY from %d\n", id, from);
                break;
            }
            case CS_RELEASE: {
                if (queue.info[0].id == from) {
                    pop();
                }

                // log release
                fprintf(stderr, "process %d CS_RELEASE from %d\n", id, from);
                break;
            }
            case DONE: {
                set_done(from);

                // log done
                fprintf(stderr, "process %d DONE from %d\n", id, from);
                break;
            }
            default:
                break;
        }
    }
    return 0;
}

int release_cs(const void *self) {
    pop();

    // create message with release type
    Message release = createMessage(MESSAGE_MAGIC, 0, 0, 0, CS_RELEASE);

    // set replies to 1 for self, 0 for others
    for (int i = 1; i <= process_count; i++) {
        queue.replies[i] = (id == i) ? 1 : 0;
    }

    // send release to all processes
    send_multicast(&id, &release);

    return 0;
}

void set_done(int i) {
    queue.done[i] = 1;
}

