import * as XLSX from 'xlsx';

function findMergedCells(filePath: string) {
  // Load the Excel workbook
  const workbook = XLSX.readFile(filePath, { cellStyles: true });

  const mergedCells: { [sheetName: string]: string[] } = {};

  // Iterate over all worksheets in the workbook
  for (const sheetName of workbook.SheetNames) {
    const sheet = workbook.Sheets[sheetName];
    // Iterate over all merged cell ranges in the worksheet
    const mergedRanges = sheet['!merges'] || [];
    for (const mergedRange of mergedRanges) {
      // Extract information about the merged cell range
      const { s, e } = mergedRange;
      const minRow = s.r + 1;
      const minCol = s.c + 1;
      const maxRow = e.r + 1;
      const maxCol = e.c + 1;
      const rangeString = `${XLSX.utils.encode_cell({ r: minRow - 1, c: minCol - 1 })}:${XLSX.utils.encode_cell({ r: maxRow - 1, c: maxCol - 1 })}`;

      // Add the merged cell range to the dictionary
      if (sheetName in mergedCells) {
        mergedCells[sheetName].push(rangeString);
      } else {
        mergedCells[sheetName] = [rangeString];
      }
    }
  }

  // Print the merged cell ranges for each worksheet
  for (const sheetName in mergedCells) {
    console.log(`Merged cells on sheet '${sheetName}':`);
    for (const rangeString of mergedCells[sheetName]) {
      console.log(` - ${rangeString}`);
    }
  }
}
```
