```cpp
Shader "Custom/TankTreadShader"
{
    Properties
    {
        _MainTex ("Base (RGB)", 2D) = "white" {}
        _Speed ("Speed", Range(0, 10)) = 1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 100

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
            };

            sampler2D _MainTex;
            float _Speed;

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                float2 offset = float2(_Time.y * _Speed, 0);
                fixed4 col = tex2D(_MainTex, i.uv + offset);
                return col;
            }
            ENDCG
        }
    }
    FallBack "Diffuse"
}
```
In this code, the \_MainTex property is the texture containing the tank tread pattern, and the \_Speed property controls how fast the texture scrolls. To use this shader on your tank, simply apply it to the tank tread material.

For the script, you can use the physics engine to simulate the movement of the tank treads. This involves creating a series of rigid bodies that represent the individual tread segments, and then applying forces to them to make them move. Here is an example script code:
```csharp
public class TankTread : MonoBehaviour
{
    public float speed = 5;
    public float torque = 10;
    public float spacing = 1;
    public float length = 10;

    public Rigidbody treadPrefab;

    private List<Rigidbody> treads = new List<Rigidbody>();

    void Start()
    {
        for (int i = 0; i < length / spacing; i++)
        {
            Rigidbody tread = Instantiate(treadPrefab);
            tread.transform.position = transform.position + transform.right * i * spacing;
            tread.transform.rotation = transform.rotation;
            treads.Add(tread);
        }
    }

    void FixedUpdate()
    {
        foreach (Rigidbody tread in treads)
        {
            tread.AddForce(transform.forward * speed, ForceMode.VelocityChange);
            tread.AddTorque(transform.up * torque, ForceMode.VelocityChange);
        }
    }
}
```
In this code, the speed and torque properties control how fast the treads move and turn, respectively. The spacing and length properties determine how long the treads are and how far apart they are spaced. The treadPrefab property is a reference to a prefab that contains a single tread segment (a simple box with a rigid body component).

