const http = require('http');
const { Readable } = require('stream');

// Make the first HTTP request
const req1 = http.request('http://example.com', (res1) => {
  // Make the second HTTP request
  const req2 = http.request('http://example.org', (res2) => {
    // Create a readable stream to combine the output from both requests
    const combinedStream = new Readable({
      read() {}
    });

    // Pipe the responses into the combined stream
    res1.pipe(combinedStream, { end: false });
    res2.pipe(combinedStream, { end: false });

    // End the combined stream once both responses have ended
    res1.on('end', () => {
      res2.unpipe(combinedStream);
      combinedStream.push(null);
    });
    res2.on('end', () => {
      res1.unpipe(combinedStream);
      combinedStream.push(null);
    });
  });

  req2.end();
});

req1.end();
