  const pathTranslations = {};
  for (const [key, paths] of Object.entries(TRANSLATED_PATH)) {
    for (const [locale, path] of Object.entries(paths)) {
      if (!pathTranslations[locale]) {
        pathTranslations[locale] = {};
      }
      for (const [otherLocale, otherPath] of Object.entries(paths)) {
        if (locale !== otherLocale) {
          pathTranslations[locale][otherPath] = path;
        }
      }
    }
  }

  const redirects = Object.entries(pathTranslations).flatMap(
    ([locale, localeObject]) => {
      return Object.entries(localeObject).map(
        ([rootPath, translatedPath]) => ({
          source: `/${locale}${rootPath}`,
          destination: `/${locale}${translatedPath}`,
          permanent: false,
        })
      );
    }
  );
  return redirects;
}

