```
function getValueByPath(obj, path) {
  // split the path into its individual parts
  const parts = path.split(".");

  // initialize a variable to hold the current value
  // set it to the initial object
  let value = obj;

  // iterate over each part of the path
  for (const part of parts) {
    // update the value to be the value of the current field
    value = value[part];

    // if the value is undefined, return undefined
    // (the path does not exist in the object)
    if (value === undefined) {
      return undefined;
    }
  }

  // return the final value
  return value;
}
```
