```
function getValueByPath(obj, path) {
  // split the path into its individual parts
  const parts = path.split(".");

  // if there is only one part, return the value of that field
  // from the object
  if (parts.length === 1) {
    return obj[parts[0]];
  }

  // otherwise, get the value of the first part of the path
  // from the object, and recursively call the function
  // using the value as the object and the rest of the path
  // as the new path
  const value = obj[parts[0]];
  return getValueByPath(value, parts.slice(1).join("."));
}
