```
public int[] TwoSum(int[] nums, int target) {
  // Create a map to store the indices of each number
  var map = new Dictionary<int, int>();

  // Loop through the numbers in the array
  for (int i = 0; i < nums.Length; i++) {
    // Get the current number
    int num = nums[i];

    // Check if there is a number in the map that adds up to the target
    if (map.ContainsKey(target - num)) {
      // Return the indices of the two numbers
      return new int[] { map[target - num], i };
    }

    // If the number is not in the map, add it
