    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int players = sc.nextInt();
        int[] chips = new int[players];
        for (int i = 0; i < players; i++) {
            chips[i] = 3;
        }
        while (true) {
            for (int i = 0; i < players; i++) {
