                        chips[players - 1]++;
                    } else {
                        chips[i - 1]++;
                    }
                } else if (roll.equalsIgnoreCase("R")) {
                    if (i == players - 1) {
                        chips[0]++;
                    } else {
                        chips[i + 1]++;
                    }
                } else if (roll.equalsIgnoreCase("C")) {
                    chips[i]--;
                } else {
                    System.out.println("Invalid roll.");
                }
                int remainingChips = 0;
                for (int j = 0; j < players; j++) {
                    remainingChips += chips[j];
                }
                if (remainingChips == 0) {
                    System.out.println("Game over!");
                    return;
                }
            }
        }
    }
}
