package com.example.mymod;

import net.minecraft.block.Block;
import net.minecraft.block.material.Material;
import net.minecraft.client.renderer.block.model.ModelResourceLocation;
import net.minecraft.creativetab.CreativeTabs;
import net.minecraft.item.Item;
import net.minecraft.item.ItemBlock;
import net.minecraftforge.client.model.ModelLoader;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.Mod.EventHandler;
import net.minecraftforge.fml.common.event.FMLInitializationEvent;
import net.minecraftforge.fml.common.event.FMLPreInitializationEvent;
import net.minecraftforge.fml.common.registry.GameRegistry;
import net.minecraftforge.fml.relauncher.Side;

@Mod(modid = MyMod.MODID, version = MyMod.VERSION)
public class MyMod
{
    public static final String MODID = "mymod";
    public static final String VERSION = "1.0";

    // Declare the block and item variables
    public static Block obsidianBox;
    public static Item obsidianBoxItem;

    @EventHandler
    public void preInit(FMLPreInitializationEvent event)
    {
        // Initialize the block and set its properties
        obsidianBox = new BlockObsidianBox(Material.ROCK);
        obsidianBox.setRegistryName("obsidian_box");
        obsidianBox.setUnlocalizedName(MODID + "." + "obsidian_box");
        obsidianBox.setCreativeTab(CreativeTabs.BUILDING_BLOCKS);

        // Initialize the item for the block and set its properties
        obsidianBoxItem = new ItemBlock(obsidianBox);
        obsidianBoxItem.setRegistryName(obsidianBox.getRegistryName());

        // Register the block and item
        GameRegistry.register(obsidianBox);
        GameRegistry.register(obsidianBoxItem);

        // Register the block model
        if (event.getSide() == Side.CLIENT) {
            ModelResourceLocation model = new ModelResourceLocation(MODID + ":" + "obsidian_box", "inventory");
            ModelLoader.setCustomModelResourceLocation(obsidianBoxItem, 0, model);
        }
    }

    @EventHandler
    public void init(FMLInitializationEvent event)
    {
        // Add recipe for obsidian box (3 obsidian blocks in a row)
        GameRegistry.addRecipe(new ItemStack(obsidianBox),
                "ooo",
                "o o",
                "ooo",
                'o', Blocks.OBSIDIAN);
    }
}
```
