package awele.bot.ligmabot;

import awele.core.Board;

public class MCTSNode {
 private int player;
 private Board board;
 private MCTSNode parent;
 private MCTSNode[] children;
 private int nbVisits;
 private double totalReward;
 private boolean[] triedMoves;

 public MCTSNode(int player, Board board, MCTSNode parent) {
 this.player = player;
 this.board = board;
 this.parent = parent;
 this.children = new MCTSNode[Board.NB\_HOLES];
 this.nbVisits = 0;
 this.totalReward = 0;
 this.triedMoves = new boolean[Board.NB\_HOLES];
 }

 public int getUntriedMove() {
 for (int i = 0; i < Board.NB\_HOLES; i++) {
 if (!triedMoves[i]) {
 triedMoves[i] = true;
 return i;
 }
 }
 return -1; // No untried moves left
 }

 public int getPlayer() {
 return player;
 }

 public Board getBoard() {
 return board;
 }

 public MCTSNode getParent() {
 return parent;
 }

 public MCTSNode getChild(int index) {
 return children[index];
 }

 public void setChild(int index, MCTSNode child) {
 children[index] = child;
 }

 public int getNbVisits() {
 return nbVisits;
 }

 public double getTotalReward() {
 return totalReward;
 }

 public void incrementNbVisits() {
 nbVisits++;
 }

 public void incrementTotalReward(double reward) {
 totalReward += reward;
 }

 boolean isGameOver() {
 int player = board.getCurrentPlayer();
 int otherPlayer = Board.otherPlayer(player);
 boolean[] validMovesCurrentPlayer = board.validMoves(player);
 boolean[] validMovesOtherPlayer = board.validMoves(otherPlayer);

 boolean currentPlayerHasMove = false;
 boolean otherPlayerHasMove = false;

 for (boolean move : validMovesCurrentPlayer) {
 if (move) {
 currentPlayerHasMove = true;
 break;
 }
 }

 for (boolean move : validMovesOtherPlayer) {
 if (move) {
 otherPlayerHasMove = true;
 break;
 }
 }

 boolean noValidMoves = !currentPlayerHasMove && !otherPlayerHasMove;
 boolean scoreReached = board.getScore(player) >= 25 || board.getScore(otherPlayer) >= 25;

 return noValidMoves || scoreReached;
 }

 public MCTSNode getBestChild(double explorationConstant) {
 MCTSNode bestChild = null;
 double bestValue = Double.NEGATIVE\_INFINITY;

 for (MCTSNode child : children) {
 if (child != null) {
 double childValue = (child.getTotalReward() / child.getNbVisits()) + explorationConstant \* Math.sqrt(Math.log(nbVisits) / child.getNbVisits());
 if (childValue > bestValue) {
 bestValue = childValue;
 bestChild = child;
 }
 }
 }
 return bestChild;
 }
}
