public class LigmaBot extends awele.bot.CompetitorBot {
 private final double explorationConstant = Math.sqrt(2);
 private final int timeLimit = 100; // Durée d'exécution de MCTS en millisecondes
 private Random random;

 public LigmaBot() throws InvalidBotException {
 this.setBotName("LigmaBot");
 this.setAuthors("Adel Souilah", "Louis Wagner");
 }

 @Override
 public void initialize() {
 this.random = new Random();
 }

 @Override
 public void finish() {}

 @Override
 public void learn() {}

 @Override
 public double[] getDecision(Board board) {
 MCTSNode root = new MCTSNode(board.getCurrentPlayer(), board, null);

 // Vérifiez si le jeu est terminé
 if (root.isGameOver()) {
 // Le jeu est terminé, retournez un tableau avec des zéros.
 double[] decisions = new double[Board.NB\_HOLES];
 Arrays.fill(decisions, 0.0);
 return decisions;
 }

 long startTime = System.currentTimeMillis();
 long endTime = startTime + timeLimit;

 while (System.currentTimeMillis() < endTime) {
 MCTSNode node = select(root);
 int result = simulate(node);
 backpropagate(node, result);
 }

 double[] decisions = new double[Board.NB\_HOLES];
 for (int i = 0; i < Board.NB\_HOLES; i++) {
 MCTSNode child = root.getChild(i);
 if (child != null) {
 decisions[i] = child.getNbVisits();
 } else {
 decisions[i] = 0;
 }
 }
 return decisions;
 }

 private MCTSNode select(MCTSNode node) {
 while (!node.isGameOver()) {
 MCTSNode bestChild = node.getBestChild(explorationConstant);
 if (bestChild == null) {
 return expand(node);
 } else {
 node = bestChild;
 }
 }
 return node;
 }

 private MCTSNode expand(MCTSNode parent) {
 int move = parent.getUntriedMove();
 if (move >= 0) {
 Board childBoard;
 try {
 childBoard = parent.getBoard().playMoveSimulationBoard(parent.getBoard().getCurrentPlayer(), getOneHotDecision(move));
 MCTSNode child = new MCTSNode(Board.otherPlayer(parent.getBoard().getCurrentPlayer()), childBoard, parent);
 parent.setChild(move, child);
 return child;
 } catch (InvalidBotException e) {
 // Ignore invalid moves
 }
 }
 return parent; // All moves have been tried, return the parent
 }
 private int simulate(MCTSNode node) {
 Board board = node.getBoard();
 int player = board.getCurrentPlayer();
 double[] randomDecision = getRandomDecision();
 try {
 int score = board.playMoveSimulationScore(player, randomDecision);
 return score;
 } catch (InvalidBotException e) {
 // Ignore invalid moves in the simulation
 return 0;
 }
 }

 private void backpropagate(MCTSNode node, int result) {
 while (node != null) {
 node.incrementNbVisits();
 node.incrementTotalReward(result);
 node = node.getParent();
 }
 }

 private double[] getRandomDecision() {
 double[] decision = new double[Board.NB\_HOLES];
 int randomIndex = random.nextInt(Board.NB\_HOLES);
 decision[randomIndex] = 1;
 return decision;
 }

 private double[] getOneHotDecision(int index
 ) {
 double[] decision = new double[Board.NB\_HOLES];
 decision[index] = 1;
 return decision;
 }

 @Override
 public String toString() {
 return "LigmaBot";
 }
}

