private double minmax(Board board, int player, int depth, double alpha, double beta) throws InvalidBotException {
    if (depth == 0 || board.gameOver()) {
        return evaluate(board, player);
    }
    if (player == board.getCurrentPlayer()) {
        double value = Double.NEGATIVE_INFINITY;
        for (int move = 0; move < Board.NB_HOLES; move++) {
            if (board.validMove(player, move)) {
                value = Math.max(value, minmax(board.playMove(player, move), Board.otherPlayer(player), depth - 1, alpha, beta));
                alpha = Math.max(alpha, value);
                if (beta <= alpha) {
