                value = Math.min(value, minmax(board.playMove(player, move), Board.otherPlayer(player), depth - 1, alpha, beta));
                beta = Math.min(beta, value);
                if (beta <= alpha) {
                    break;
                }
            }
        }
        return value;
    }
}
