using System;
using System.Collections.Concurrent;
using System.Threading;

class Throttler
{
    private int _requestsPerSecond;
    private int _requestsPerMinute;
    private int _requestsPerHour;
    private ConcurrentDictionary<string, Tuple<int, int, int>> _clientCounters;
    private readonly object _locker = new object();

    public Throttler(int requestsPerSecond, int requestsPerMinute, int requestsPerHour)
    {
        _requestsPerSecond = requestsPerSecond;
        _requestsPerMinute = requestsPerMinute;
        _requestsPerHour = requestsPerHour;
        _clientCounters = new ConcurrentDictionary<string, Tuple<int, int, int>>();
    }

    public void Throttle(string clientId)
    {
        lock (_locker)
        {
            var counters = _clientCounters.GetOrAdd(clientId, (key) => new Tuple<int, int, int>(0, 0, 0));
            if (counters.Item1 >= _requestsPerSecond)
            {
                // Wait for the next second
                var delay = 1000 - (DateTime.Now.Millisecond);
                Thread.Sleep(delay);
                counters = new Tuple<int, int, int>(0, counters.Item2 + 1, counters.Item3);
            }

            if (counters.Item2 >= _requestsPerMinute)
            {
                // Wait for the next minute
                var delay = 60000 - (DateTime.Now.Millisecond + (DateTime.Now.Second * 1000));
                Thread.Sleep(delay);
                counters = new Tuple<int, int, int>(0, 0, counters.Item3 + 1);
            }

            if (counters.Item3 >= _requestsPerHour)
            {
                // Wait for the next hour
                var delay = 3600000 - (DateTime.Now.Millisecond + (DateTime.Now.Second * 1000) + (DateTime.Now.Minute * 60000));
                Thread.Sleep(delay);
                counters = new Tuple<int, int, int>(0, 0, 0);
            }

            _clientCounters[clientId] = new Tuple<int, int, int>(counters.Item1 + 1, counters.Item2, counters.Item3);
        }
    }
}
