@Configuration
@EnableStateMachine
public class SimpleStateMachineConfig extends EnumStateMachineConfigurerAdapter<States, Events> {

    @Override
    public void configure(StateMachineConfigurationConfigurer<States, Events> config) throws Exception {
        config
            .withConfiguration()
            .autoStartup(true);
    }

    @Override
    public void configure(StateMachineStateConfigurer<States, Events> states) throws Exception {
        states
            .withStates()
            .initial(States.WAITING)
            .states(EnumSet.allOf(States.class));
    }

    @Override
    public void configure(StateMachineTransitionConfigurer<States, Events> transitions) throws Exception {
        transitions
            .withExternal()
                .source(States.WAITING).target(States.PROCESSING)
                .event(Events.START_PROCESSING)
                .and()
            .withExternal()
                .source(States.PROCESSING).target(States.COMPLETED)
                .event(Events.PROCESSING_COMPLETED)
                .and()
            .withExternal()
                .source(States.PROCESSING).target(States.FAILED)
                .event(Events.PROCESSING_FAILED);
    }

    @Override
    public void configure(StateMachineModelConfigurer<States, Events> model) throws Exception {
        model
            .withModel()
            .factory(modelFactory());
    }

    @Bean
    public StateMachineModelFactory<States, Events> modelFactory() {
        return new EnumStateMachineModelFactory<States, Events>();
    }
}

enum States {
