    class Program
    {
        static void Main(string[] args)
        {
            // Initialize OpenNLP NameFinder
            var modelStream = new java.io.FileInputStream("en-ner-person.bin");
            var model = new TokenNameFinderModel(modelStream);
            var nameFinder = new NameFinderME(model);

            // Initialize Twitter API
            var credentials = new TwitterCredentials("CONSUMER_KEY", "CONSUMER_SECRET", "ACCESS_TOKEN", "ACCESS_TOKEN_SECRET");
            Auth.SetCredentials(credentials);

            // Text to search for famous people
            var text = "I love reading books by J.K. Rowling and watching movies with Tom Hanks.";

            // Use OpenNLP to find names of people in the text
            var tokens = WhitespaceTokenizer.INSTANCE.tokenize(text);
            var spans = nameFinder.find(tokens);

            // Check if each identified person has a Twitter account
            foreach (var span in spans)
            {
