function generate_apple_client_secret($team_id, $client_id, $key_id, $private_key_path) {
    // Load the private key
    $private_key = file_get_contents($private_key_path);
    $private_key_contents = openssl_get_privatekey($private_key);

    // Set the header
    $header = array(
        "alg" => "ES256",
        "kid" => $key_id,
        "typ" => "JWT"
    );

    // Set the payload
    $payload = array(
        "iss" => $team_id,
        "iat" => time(),
        "exp" => time() + (86400 * 180),
        "aud" => "https://appleid.apple.com",
        "sub" => $client_id,
    );

    // Encode the JWT
    $jwt = JWT::encode($payload, $private_key_contents, 'ES256', $key_id);

    return $jwt;
}
