 \* Helper method to create a JSON error.
 \*
 \* @param int $errno An error number from json\_last\_error()
 \*
 \* @return void
 \*/
 private static function handleJsonError($errno)
 {
 $messages = array(
 JSON\_ERROR\_DEPTH => 'Maximum stack depth exceeded',
 JSON\_ERROR\_STATE\_MISMATCH => 'Invalid or malformed JSON',
 JSON\_ERROR\_CTRL\_CHAR => 'Unexpected control character found',
 JSON\_ERROR\_SYNTAX => 'Syntax error, malformed JSON',
 JSON\_ERROR\_UTF8 => 'Malformed UTF-8 characters' //PHP >= 5.3.3
 );
 throw new \DomainException(
 isset($messages[$errno])
 ? $messages[$errno]
 : 'Unknown JSON error: ' . $errno
 );
 }

