 \* Get the number of bytes in cryptographic strings.
 \*
 \* @param string
 \*
 \* @return int
 \*/
 private static function safeStrlen($str)
 {
 if (function\_exists('mb\_strlen')) {
 return mb\_strlen($str, '8bit');
 }
 return strlen($str);
 }
