  let dp = new Array(text1.length + 1)
  for i in 0...text1.length + 1:
    dp[i] = new Array(text2.length + 1)

  // iterate over the characters of the first string
  for i in 1...text1.length + 1:
    // iterate over the characters of the second string
    for j in 1...text2.length + 1:
      // if the characters at the current position are the same,
      // we can include this character in the common subsequence
      // and move to the next position in both strings
      if text1[i-1] == text2[j-1]:
        dp[i][j] = dp[i-1][j-1] + 1
      else:
        // if the characters are different, take the maximum of the two possibilities:
        // either moving forward in the first string, or moving forward in the second string
        dp[i][j] = max(dp[i][j-1], dp[i-1][j])

  // the length of the longest common subsequence is the value stored in the last cell of the array
  return dp[text1.length][text2.length]
```
